[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SnapFrame — Capture, Create & Share What You Love</title>
<meta name="description" content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800&family=Cabinet+Grotesk:wght@700;800;900&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --black: #000000;
  --white: #ffffff;
  --off-white: #FAFAFA;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --purple: #7638FA;
  --purple-light: #9B6DFC;
  --purple-dark: #5A1FD6;
  --orange: #FF7A00;
  --orange-light: #FF9E40;
  --magenta: #E040A0;
  --gradient-brand: linear-gradient(135deg, #7638FA 0%, #E040A0 50%, #FF7A00 100%);
  --gradient-hero: linear-gradient(160deg, #7638FA 0%, #C838C8 40%, #FF7A00 100%);
  --gradient-warm: linear-gradient(135deg, #FF7A00 0%, #E040A0 100%);
  --gradient-cool: linear-gradient(135deg, #7638FA 0%, #3B82F6 100%);
  --font-display: 'Cabinet Grotesk', 'Plus Jakarta Sans', sans-serif;
  --font-body: 'Plus Jakarta Sans', system-ui, sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 25px -3px rgba(0,0,0,0.08), 0 4px 10px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 40px -8px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ============================================
   HEADER
   ============================================ */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--gray-100);
  transition: box-shadow 0.3s ease;
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.hamburger {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  transition: background 0.2s;
}

.hamburger:hover { background: var(--gray-100); }

.hamburger svg { width: 22px; height: 22px; }

.logo {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.5px;
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 8px;
}

.header-nav a {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  color: var(--gray-600);
  border-radius: var(--radius-full);
  transition: all 0.2s;
}

.header-nav a:hover {
  color: var(--gray-900);
  background: var(--gray-100);
}

.btn-login {
  padding: 8px 20px !important;
  font-weight: 600 !important;
  color: var(--white) !important;
  background: var(--black) !important;
  border-radius: var(--radius-full) !important;
  font-size: 14px !important;
  transition: all 0.2s !important;
}

.btn-login:hover {
  background: var(--gray-800) !important;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

/* Mobile nav overlay */
.mobile-nav-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 998;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.mobile-nav-overlay.active {
  opacity: 1;
}

.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 300px;
  max-width: 85vw;
  background: var(--white);
  z-index: 999;
  transform: translateX(-100%);
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  overflow-y: auto;
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  border-bottom: 1px solid var(--gray-100);
}

.mobile-nav-close {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  transition: background 0.2s;
}

.mobile-nav-close:hover { background: var(--gray-100); }

.mobile-nav-links {
  padding: 16px;
}

.mobile-nav-links a {
  display: block;
  padding: 14px 16px;
  font-size: 16px;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: var(--radius-md);
  transition: all 0.2s;
}

.mobile-nav-links a:hover {
  background: var(--gray-50);
  color: var(--gray-900);
}

.mobile-nav-links .btn-login-mobile {
  display: inline-block;
  margin: 16px;
  padding: 12px 32px;
  font-weight: 600;
  color: var(--white);
  background: var(--black);
  border-radius: var(--radius-full);
  text-align: center;
  width: calc(100% - 32px);
}

@media (max-width: 768px) {
  .hamburger { display: flex; }
  .header-nav { display: none; }
  .mobile-nav, .mobile-nav-overlay { display: block; }
}

/* ============================================
   HERO
   ============================================ */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 120px 24px 80px;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--gradient-hero);
  opacity: 0.06;
}

.hero::after {
  content: '';
  position: absolute;
  top: -40%;
  right: -20%;
  width: 80%;
  height: 80%;
  background: radial-gradient(circle, rgba(118,56,250,0.12) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero-glow {
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 60%;
  height: 60%;
  background: radial-gradient(circle, rgba(255,122,0,0.08) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 820px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px 6px 8px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 600;
  color: var(--gray-700);
  margin-bottom: 32px;
  box-shadow: var(--shadow-sm);
  animation: fadeInUp 0.6s ease-out 0.1s both;
}

.hero-badge-dot {
  width: 8px;
  height: 8px;
  background: var(--purple);
  border-radius: 50%;
  animation: pulse 2s infinite;
}

.hero h1 {
  font-family: var(--font-display);
  font-size: clamp(36px, 6vw, 72px);
  font-weight: 900;
  line-height: 1.08;
  letter-spacing: -2px;
  color: var(--gray-900);
  margin-bottom: 28px;
  animation: fadeInUp 0.6s ease-out 0.2s both;
}

.hero h1 .gradient-text {
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: clamp(16px, 2vw, 20px);
  color: var(--gray-500);
  max-width: 560px;
  margin: 0 auto 40px;
  line-height: 1.7;
  animation: fadeInUp 0.6s ease-out 0.35s both;
}

.hero-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 16px 36px;
  font-size: 16px;
  font-weight: 700;
  color: var(--white);
  background: var(--gradient-brand);
  border-radius: var(--radius-full);
  box-shadow: 0 4px 20px rgba(118,56,250,0.35);
  transition: all 0.3s ease;
  animation: fadeInUp 0.6s ease-out 0.5s both;
}

.hero-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(118,56,250,0.45);
}

.hero-cta svg {
  width: 18px;
  height: 18px;
  transition: transform 0.3s;
}

.hero-cta:hover svg { transform: translateX(3px); }

.hero-scroll-hint {
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: var(--gray-400);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 1px;
  text-transform: uppercase;
  animation: fadeInUp 0.6s ease-out 0.7s both;
}

.scroll-line {
  width: 1px;
  height: 40px;
  background: linear-gradient(to bottom, var(--gray-300), transparent);
  animation: scrollLine 2s infinite;
}

/* ============================================
   CONTENT SECTIONS (Features, Safety, Creators)
   ============================================ */
.section {
  padding: 100px 0;
  position: relative;
}

.section-features { background: var(--white); }
.section-safety { background: var(--gray-50); }
.section-creators { background: var(--white); }

.section-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.content-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.content-card.reverse {
  direction: rtl;
}

.content-card.reverse > * {
  direction: ltr;
}

.content-text {
  max-width: 520px;
}

.section-label {
  display: inline-block;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 16px;
  padding: 4px 12px;
  border-radius: var(--radius-full);
}

.label-features {
  color: var(--purple);
  background: rgba(118,56,250,0.08);
}

.label-safety {
  color: #059669;
  background: rgba(5,150,105,0.08);
}

.label-creators {
  color: var(--orange);
  background: rgba(255,122,0,0.08);
}

.content-text h2 {
  font-family: var(--font-display);
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -1px;
  color: var(--gray-900);
  margin-bottom: 20px;
}

.content-text p {
  font-size: 16px;
  color: var(--gray-500);
  line-height: 1.7;
  margin-bottom: 28px;
}

.section-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
  font-weight: 700;
  transition: all 0.2s;
}

.section-link svg {
  width: 16px;
  height: 16px;
  transition: transform 0.2s;
}

.section-link:hover svg { transform: translateX(4px); }

.link-features { color: var(--purple); }
.link-features:hover { color: var(--purple-dark); }

.link-safety { color: #059669; }
.link-safety:hover { color: #047857; }

.link-creators { color: var(--orange); }
.link-creators:hover { color: #E56D00; }

.content-visual {
  position: relative;
  aspect-ratio: 1;
  border-radius: var(--radius-xl);
  overflow: hidden;
}

.visual-features {
  background: linear-gradient(135deg, #EDE9FE 0%, #F3E8FF 50%, #FCE7F3 100%);
}

.visual-safety {
  background: linear-gradient(135deg, #D1FAE5 0%, #ECFDF5 50%, #F0FDFA 100%);
}

.visual-creators {
  background: linear-gradient(135deg, #FFF7ED 0%, #FFEDD5 50%, #FEF3C7 100%);
}

.visual-inner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.visual-icon {
  width: 120px;
  height: 120px;
  border-radius: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-xl);
}

.visual-icon.purple { background: var(--gradient-brand); }
.visual-icon.green { background: linear-gradient(135deg, #059669, #10B981); }
.visual-icon.orange { background: var(--gradient-warm); }

.visual-icon svg { width: 56px; height: 56px; color: white; }

.floating-pill {
  position: absolute;
  padding: 10px 18px;
  background: var(--white);
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-lg);
  font-size: 13px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
}

.pill-1 { top: 20%; left: 8%; animation: float 6s ease-in-out infinite; }
.pill-2 { bottom: 25%; right: 8%; animation: float 6s ease-in-out 2s infinite; }
.pill-3 { top: 12%; right: 15%; animation: float 6s ease-in-out 1s infinite; }
.pill-4 { bottom: 15%; left: 12%; animation: float 6s ease-in-out 3s infinite; }

.pill-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

@media (max-width: 768px) {
  .content-card {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .content-card.reverse { direction: ltr; }
  .content-visual { max-width: 400px; margin: 0 auto; }
  .section { padding: 64px 0; }
}

/* ============================================
   TAGLINE BANNER
   ============================================ */
.tagline-banner {
  position: relative;
  padding: 80px 24px;
  text-align: center;
  background: var(--black);
  overflow: hidden;
}

.tagline-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--gradient-hero);
  opacity: 0.15;
}

.tagline-banner h2 {
  position: relative;
  z-index: 1;
  font-family: var(--font-display);
  font-size: clamp(28px, 5vw, 56px);
  font-weight: 900;
  letter-spacing: -1.5px;
  line-height: 1.15;
  color: var(--white);
}

/* ============================================
   NEWS SECTION
   ============================================ */
.section-news {
  padding: 100px 0;
  background: var(--gray-50);
  overflow: hidden;
}

.news-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  max-width: 1200px;
  margin: 0 auto 48px;
  padding: 0 24px;
  gap: 16px;
}

.news-header-left .news-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--purple);
  margin-bottom: 8px;
}

.news-header-left h2 {
  font-family: var(--font-display);
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 800;
  letter-spacing: -1px;
  color: var(--gray-900);
}

.news-view-more {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 15px;
  font-weight: 700;
  color: var(--purple);
  transition: all 0.2s;
  padding: 8px 0;
}

.news-view-more:hover { color: var(--purple-dark); }
.news-view-more svg { width: 16px; height: 16px; transition: transform 0.2s; }
.news-view-more:hover svg { transform: translateX(4px); }

.news-carousel-wrapper {
  position: relative;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.news-carousel {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 8px;
}

.news-carousel::-webkit-scrollbar { display: none; }

.news-card {
  flex: 0 0 320px;
  scroll-snap-align: start;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  transition: all 0.3s ease;
  cursor: pointer;
}

.news-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--gray-200);
}

.news-card-thumb {
  height: 180px;
  position: relative;
  overflow: hidden;
}

.news-card:nth-child(1) .news-card-thumb { background: linear-gradient(135deg, #7638FA, #C838C8); }
.news-card:nth-child(2) .news-card-thumb { background: linear-gradient(135deg, #FF7A00, #FF9E40); }
.news-card:nth-child(3) .news-card-thumb { background: linear-gradient(135deg, #3B82F6, #7638FA); }
.news-card:nth-child(4) .news-card-thumb { background: linear-gradient(135deg, #E040A0, #FF7A00); }

.news-card-thumb-icon {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.news-card-thumb-icon svg {
  width: 48px;
  height: 48px;
  color: rgba(255,255,255,0.4);
}

.news-card-body {
  padding: 20px;
}

.news-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}

.news-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  background: var(--gray-100);
  color: var(--gray-600);
}

.news-card:nth-child(1) .news-tag { background: rgba(118,56,250,0.1); color: var(--purple); }
.news-card:nth-child(2) .news-tag { background: rgba(255,122,0,0.1); color: var(--orange); }
.news-card:nth-child(3) .news-tag { background: rgba(59,130,246,0.1); color: #3B82F6; }
.news-card:nth-child(4) .news-tag { background: rgba(224,64,160,0.1); color: var(--magenta); }

.news-card-title {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.45;
  color: var(--gray-900);
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.news-card-date {
  font-size: 13px;
  color: var(--gray-400);
  font-weight: 500;
}

@media (max-width: 768px) {
  .news-card { flex: 0 0 280px; }
  .news-header { flex-direction: column; align-items: flex-start; }
}

/* ============================================
   CTA DOWNLOAD
   ============================================ */
.cta-download {
  position: relative;
  padding: 100px 24px;
  text-align: center;
  background: var(--white);
  overflow: hidden;
}

.cta-download::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(118,56,250,0.06) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.cta-content {
  position: relative;
  z-index: 1;
}

.cta-download h2 {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 60px);
  font-weight: 900;
  letter-spacing: -1.5px;
  line-height: 1.1;
  color: var(--gray-900);
  margin-bottom: 8px;
}

.cta-download .subtitle {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 60px);
  font-weight: 900;
  letter-spacing: -1.5px;
  line-height: 1.1;
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 40px;
}

.cta-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.store-btn {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 14px 28px;
  background: var(--black);
  color: var(--white);
  border-radius: var(--radius-md);
  transition: all 0.3s ease;
  box-shadow: var(--shadow-md);
}

.store-btn:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-xl);
  background: var(--gray-800);
}

.store-btn svg { width: 24px; height: 24px; }

.store-btn-text {
  text-align: left;
}

.store-btn-text .small {
  font-size: 10px;
  font-weight: 500;
  opacity: 0.7;
  display: block;
  line-height: 1;
  margin-bottom: 2px;
}

.store-btn-text .name {
  font-size: 16px;
  font-weight: 700;
  line-height: 1;
}

/* ============================================
   FOOTER
   ============================================ */
.footer {
  background: var(--gray-900);
  color: var(--gray-300);
  padding: 64px 0 0;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px 48px;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
}

.footer-col h3 {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--white);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 14px;
  color: var(--gray-400);
  transition: color 0.2s;
  line-height: 1.8;
}

.footer-col a:hover { color: var(--white); }

.footer-col a .external-icon {
  display: inline;
  margin-left: 3px;
  font-size: 11px;
  opacity: 0.6;
}

.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 24px;
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-lang {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: rgba(255,255,255,0.08);
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 500;
  color: var(--gray-300);
  border: 1px solid rgba(255,255,255,0.1);
  cursor: pointer;
  transition: all 0.2s;
}

.footer-lang:hover { background: rgba(255,255,255,0.12); }

.footer-lang svg { width: 14px; height: 14px; }

.footer-social {
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--gray-400);
  transition: all 0.2s;
}

.footer-social a:hover {
  color: var(--white);
  background: rgba(255,255,255,0.08);
}

.footer-social a svg { width: 18px; height: 18px; }

.footer-legal {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 13px;
  color: var(--gray-500);
}

.footer-legal a {
  color: var(--gray-500);
  transition: color 0.2s;
  padding: 2px 0;
}

.footer-legal a:hover { color: var(--white); }

.footer-legal span { color: var(--gray-600); }

@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 28px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* ============================================
   ANIMATIONS
   ============================================ */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-12px); }
}

@keyframes scrollLine {
  0% { opacity: 1; transform: scaleY(1); }
  50% { opacity: 0.3; transform: scaleY(0.5); }
  100% { opacity: 1; transform: scaleY(1); }
}

/* Scroll reveal */
.reveal {
  opacity: 0;
  transform: translateY(32px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Stagger children */
.reveal-stagger > * {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.reveal-stagger.visible > *:nth-child(1) { transition-delay: 0s; }
.reveal-stagger.visible > *:nth-child(2) { transition-delay: 0.1s; }
.reveal-stagger.visible > *:nth-child(3) { transition-delay: 0.2s; }
.reveal-stagger.visible > *:nth-child(4) { transition-delay: 0.3s; }

.reveal-stagger.visible > * {
  opacity: 1;
  transform: translateY(0);
}

/* Grain overlay */
body::after {
  content: '';
  position: fixed;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.03'/%3E%3C/svg%3E");
  pointer-events: none;
  z-index: 9999;
  opacity: 0.4;
}
</style>
</head>
